using System.Collections.Generic;public class Solution{Dictionary<string,PriorityQueue<string,string>>g=new();LinkedList<string>o=new();void F(string u){if(g.ContainsKey(u))while(g[u].Count>0){string v=g[u].Dequeue();F(v);}o.AddFirst(u);}public IList<string> FindItinerary(IList<IList<string>>t){foreach(var x in t){if(!g.ContainsKey(x[0]))g[x[0]]=new();g[x[0]].Enqueue(x[1],x[1]);}F("JFK");return new List<string>(o);}}
